// Program catalogue: supplied durations are in months.
const programs=[["Development","Full Stack Development",6,"Build complete web applications.","Frontend foundations|Backend APIs and databases|Full-stack projects and deployment"],["Development","Frontend Development",4,"Create responsive, accessible interfaces.","HTML, CSS and responsive layouts|JavaScript and component-based interfaces|Practical UI projects"],["Development","Backend Development",4,"Build the systems behind modern applications.","Server-side programming and APIs|Databases, authentication and validation|Backend projects and testing"],["Data & AI","Data Analyst",4,"Turn data into clear, useful insights.","Data cleaning and exploration|SQL, reporting and dashboards|Communicating business insights"],["Data & AI","Data Science",6,"Explore patterns and solve data-driven problems.","Python and statistics|Data preparation and analysis|Experiments and evaluation"],["Data & AI","Generative AI",6,"Build practical workflows with generative AI.","Prompting and model capabilities|AI-assisted workflows and applications|Responsible use and evaluation"],["Business","Human Resource",3,"Build a foundation in people operations.","Recruitment and communication|Employee lifecycle and HR processes|Workplace scenarios and documentation"],["Business","Business Analyst",4,"Connect business needs with actionable requirements.","Requirement gathering and analysis|Process mapping and documentation|Stakeholder communication"],["Data & AI","Artificial Intelligence",6,"Understand and apply intelligent systems.","AI foundations and applications|Data-driven problem solving|Practical projects and responsible AI"],["Data & AI","Machine Learning",6,"Prepare, train and evaluate predictive models.","Supervised and unsupervised learning|Feature preparation and evaluation|Practical model-building projects"],["Business","Communication Skills",3,"Communicate clearly and confidently in professional settings.","Speaking and listening foundations|Workplace communication and presentation|Interview communication and practical exercises",7999]];
const services=[["Web & App Development","Responsive websites and applications built around your users and business needs."],["AI Automation","Streamline repetitive workflows and put AI to work in practical business processes."],["Business Analysis","Clarify requirements, map processes and identify opportunities for improvement."],["Data Analysis","Organise data, uncover patterns and present useful insights through reports and dashboards."],["SEO","Improve search visibility through technical, on-page and content optimisation."],["Digital Marketing","Plan and execute digital campaigns around your audience, goals and channels."],["Lead Generation","Develop targeted lead journeys and outreach strategies for your business."],["Google Business Profile Optimization","Improve business information, local content and profile presentation for local discovery."]];
const benefits=[["Live Training","Learn with instructor-led sessions and practical guidance."],["Recorded Sessions","Revisit lessons and reinforce your understanding."],["Doubt Sessions","Ask questions and work through concepts that need clarity."],["Placement Preparation","Prepare for tests and interviews with focused practice."],["Placement Support","Get guidance as you explore relevant career opportunities."],["Training & Internship Certificates","Document your completed learning and internship experience."]];
const programPageSlugs={"Full Stack Development":"full-stack-development","Frontend Development":"frontend-development","Backend Development":"backend-development","Data Analyst":"data-analyst","Data Science":"data-science","Generative AI":"generative-ai","Human Resource":"human-resource","Business Analyst":"business-analyst","Artificial Intelligence":"artificial-intelligence","Machine Learning":"machine-learning","Communication Skills":"communication-skills"};
const careerRoles=["Business Development Executive","Sales Executive","Lead Generation Executive"];
const courseGrid=document.querySelector("#course-cards");
function renderPrograms(category){const list=programs.filter(p=>category==="All"||p[0]===category);courseGrid.replaceChildren();list.forEach(([cat,name,months,description,topics],i)=>{const card=document.createElement("article");card.className="course-card";card.innerHTML='<div class="program-art"><span class="program-symbol" aria-hidden="true">◇</span><div class="card-meta"><span>'+cat+' / LEARNING PATH</span><b>'+months+' MONTHS</b></div></div><div class="program-body"><h3>'+name+'</h3><p>'+description+'</p><div class="program-tags">'+topics.split("|").map(t=>"<span>"+t+"</span>").join("")+'</div><div class="card-foot"><span>Live + recorded · Practical learning</span><a href="program-'+programPageSlugs[name]+'.html">View Program Details</a></div></div><a class="course-card-link" aria-label="Explore '+name+'" href="program-'+programPageSlugs[name]+'.html"></a>';courseGrid.append(card)});document.querySelector("#results").textContent=list.length+" programs to explore"}
if(courseGrid)renderPrograms("All");
document.querySelectorAll("[data-category]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-category]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));renderPrograms(b.dataset.category)}));
if(document.querySelector("#benefit-cards"))document.querySelector("#benefit-cards").innerHTML=benefits.map(([name,description],i)=>'<article><span class="number">0'+(i+1)+'</span><h3>'+name+'</h3><p>'+description+'</p></article>').join("");
if(document.querySelector("#service-cards"))document.querySelector("#service-cards").innerHTML=services.map(([name,description],i)=>'<article><span class="number">0'+(i+1)+'</span><h3>'+name+'</h3><p>'+description+'</p><a href="#enquiry" data-type="IT Services" data-interest="'+name+'">Discuss Your Project</a></article>').join("");
// Enquiry routing: every program/service CTA selects its matching option.
const type=document.querySelector("#enquiry-type"),interest=document.querySelector("#interest");
function fillInterests(){if(!interest||!type)return;interest.replaceChildren(new Option("Choose a program or service",""));const names=type.value==="Training"?programs.map(p=>p[1]):type.value==="Internship"?["Data Analytics Internship","AI/ML Internship","Web Development Internship","Business Analytics Internship","Digital Marketing Internship","UI/UX Internship","Cybersecurity Internship"]:type.value==="IT Services"?services.map(s=>s[0]):type.value==="Placement support"?["Placement support"]:type.value==="Careers"?careerRoles:["General enquiry"];names.forEach(n=>interest.add(new Option(n,n)))}
fillInterests();type?.addEventListener("change",fillInterests);
document.addEventListener("click",e=>{const a=e.target.closest("[data-interest]");if(a){if(type&&interest){type.value=a.dataset.type||"Placement support";fillInterests();interest.value=a.dataset.interest}else{e.preventDefault();location.href="contact.html?type="+encodeURIComponent(a.dataset.type||"Placement support")+"&interest="+encodeURIComponent(a.dataset.interest)+"#enquiry"}}});
const menu=document.querySelector(".menu"),nav=document.querySelector("nav");
function closeMenu(){menu.setAttribute("aria-expanded","false");nav.classList.remove("open")}
menu.addEventListener("click",()=>{const open=menu.getAttribute("aria-expanded")!=="true";menu.setAttribute("aria-expanded",String(open));nav.classList.toggle("open",open)});
nav.addEventListener("click",e=>{if(e.target.closest("a"))closeMenu()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMenu()});
const dialog=document.querySelector("#certificate-dialog");const certificatePreview=document.querySelector(".certificate");if(certificatePreview)document.querySelector("#dialog-certificate").append(certificatePreview.cloneNode(true));
document.querySelector("#show-certificate")?.addEventListener("click",()=>dialog.showModal());document.querySelector(".dialog-close").addEventListener("click",()=>dialog.close());
