document.querySelector("#enquiry-form")?.addEventListener("submit",e=>{if(location.protocol==="file:"){e.preventDefault();document.querySelector("#form-status").textContent="Please extract the website ZIP and double-click Launch Website.cmd. Email forms require a web server. You can also email qelvioratechnologies@gmail.com directly.";return}if(!e.currentTarget.reportValidity()){e.preventDefault();return}document.querySelector("#form-status").textContent="Continuing to the form service…";});

// Original Qelviora skill guides: search, category filters, practice and self-check.
const skillGuides=[["Career","Portfolio","Present your work clearly to employers and collaborators.","Choose one project and define its purpose.|Explain your own contribution and decisions.|Organise source files and remove sensitive data.|Write setup instructions with expected results.|Provide a working demonstration where appropriate.|Review the portfolio from a first-time visitor’s perspective.","Prepare a project case study with a README, screenshots and runnable instructions.","What makes a portfolio credible?","Clear evidence, your contribution and honest explanations of results and limitations."],["AI","Claude Code","Use an AI coding assistant with clear context and careful review.","Describe project structure and development constraints.|Break a change into reviewable steps.|Review the permissions needed for a task.|Give focused requests and relevant context.|Inspect changes before accepting them.|Run checks and document the resulting behaviour.","Use an assistant to make one small project change and document your review.","Should generated code be accepted without review?","No. Check correctness, permissions, security and behaviour before using it."],["Career","LinkedIn","Make your professional profile clear and relevant.","Write a headline describing your direction.|Explain skills with concrete examples.|Add projects that demonstrate your contribution.|Keep experience and education accurate.|Write concise, relevant outreach messages.|Review your profile for clarity and consistency.","Draft a profile summary and one project description.","What should support a claimed skill?","A specific example of work or learning that you can explain."],["Full Stack","Git & GitHub","Organise project history and collaborate through reviewable changes.","Inspect modified files before committing.|Create focused commits with useful messages.|Use branches for separate changes.|Review and resolve conflicting edits carefully.|Document setup and usage in the repository.|Keep credentials and generated clutter out of version control.","Publish a practice project with a branch and a reviewed change.","What belongs in a focused commit?","One coherent change that can be understood and reviewed independently."],["Frontend","JavaScript","Build interactive interfaces using clear programming foundations.","Understand values, types and comparisons.|Use functions to organise repeated operations.|Transform arrays and access object data.|Handle events and update the interface.|Manage asynchronous requests and failures.|Split reusable logic into modules.","Build a searchable catalogue using sample data.","Why handle a failed request?","To explain the problem and let the user recover instead of showing a broken interface."],["Design","UI/UX","Make product interfaces easier to understand and use.","Identify the visitor’s main task.|Arrange content using a clear hierarchy.|Choose readable type, spacing and contrast.|Design keyboard-friendly controls.|Plan loading, empty and error states.|Review the interface with representative tasks.","Redesign a confusing enquiry form and explain each improvement.","Why design an empty state?","It explains what is missing and helps users take the next useful step."],["Backend","REST APIs","Design predictable interfaces between applications.","Name resources consistently.|Choose methods that match the operation.|Validate requests and required fields.|Return meaningful status codes and errors.|Define pagination for larger collections.|Document example requests and responses.","Design an API for courses and enquiries.","What should an API error tell a client?","What failed, a useful status, and enough information to correct a valid request."],["Backend","SQL","Store structured information and query it reliably.","Model records with tables and keys.|Use constraints to protect data integrity.|Filter and order query results.|Join related tables when needed.|Aggregate values and check totals.|Use parameterised inputs and inspect query plans.","Create a practice database with courses and enquiries.","Why use query parameters?","They separate input data from SQL instructions and help prevent injection."],["Backend","Authentication","Understand identity and secure access in application development.","Distinguish identification, authentication and authorisation.|Use established password-hashing approaches.|Understand sessions and tokens.|Review secure cookie and expiry settings.|Control access to protected operations.|Check logout, expired sessions and rejected requests.","Draw and review an authentication flow for a fictional app.","Does signing in automatically grant all permissions?","No. Each protected operation still requires appropriate authorisation."],["Frontend","TypeScript","Use types to express contracts and catch mistakes earlier.","Describe values with suitable types.|Model objects and function inputs.|Use unions and narrow uncertain values.|Type component or API boundaries.|Avoid hiding problems with unnecessary any types.|Check the project and handle runtime input separately.","Add types to a small JavaScript data-processing feature.","Do static types validate external input at runtime?","No. External data still needs runtime validation."],["Frontend","React","Compose interactive interfaces from reusable components.","Break the interface into focused components.|Pass data using props.|Keep changing interface data in state.|Render lists with stable keys.|Handle forms and user events.|Use effects only when synchronising with external systems.","Build a filterable task or course list.","Why use stable list keys?","They help React identify items correctly when a list changes."],["Frontend","Next.js","Organise a web application with routes and server-aware rendering.","Map the application’s pages and routes.|Separate server work from client interactions.|Fetch and validate application data.|Handle loading and errors in the route flow.|Keep secrets outside browser code.|Prepare and check a working deployment.","Build a small catalogue with a list and a detail route.","Where should a secret API key be used?","On the server, rather than in browser-delivered code."],["Frontend","Tailwind CSS","Create consistent layouts through reusable styling decisions.","Understand utility-based styling.|Apply spacing and typography consistently.|Build responsive layout variations.|Design visible focus and interaction states.|Keep class combinations understandable.|Review repeated patterns for consistency.","Style a responsive catalogue with clear cards and forms.","What makes a consistent visual system?","Shared decisions for spacing, type, colour and interaction states."],["Backend","Express","Build server-side routes with predictable request handling.","Organise routes and middleware.|Parse and validate request bodies.|Separate business logic from transport handling.|Connect routes to application data.|Handle errors centrally and safely.|Document configuration and API usage.","Build an enquiry API using fictional data.","Why centralise error handling?","It supports consistent responses and avoids leaking internal details."],["Full Stack","Full-Stack","Connect a working interface, API and data layer.","Define the smallest useful user workflow.|Model the data needed for the workflow.|Build an interface with clear states.|Create and validate API operations.|Connect the interface to application storage.|Test and document the complete journey.","Create a fictional course enquiry tracker.","What should a complete application test cover?","The end-to-end user behaviour, including validation and failure states."],["Full Stack","Deployment","Prepare an application for use outside development.","Choose a deployment approach for the stack.|Separate configuration from source code.|Protect secrets and database credentials.|Verify build output and production settings.|Check pages and key interactions after deployment.|Document updates and recovery steps.","Deploy a static portfolio and verify its links on a phone.","Why check the deployed application?","Production configuration and runtime conditions can differ from development."],["AI","Python","Write understandable programs for data and automation tasks.","Use collections and control flow.|Organise logic with functions and modules.|Read and write structured files.|Handle exceptions with useful messages.|Call APIs with validation and error handling.|Document dependencies and how to run the tool.","Create a command-line tool that summarises a sample dataset.","Why isolate repeated logic in a function?","It makes the operation reusable, easier to test and clearer to call."],["AI","Machine Learning","Learn predictive modelling through careful experiments.","Define a prediction task and dataset.|Prepare features without leaking future information.|Separate training and evaluation data.|Compare a simple baseline with a model.|Choose metrics relevant to the task.|Inspect errors and explain limitations.","Compare baseline and model results on a practice dataset.","Why keep test data separate?","To estimate behaviour on data that was not used to fit the model."],["Data","Pandas","Prepare and summarise tabular datasets.","Inspect column types and sample records.|Find missing values and inconsistent formats.|Remove duplicates with a stated rule.|Join related datasets carefully.|Group records and calculate useful summaries.|Check the final data and document transformations.","Clean a fictional sales dataset and summarise revenue by category.","Why check row counts after a join?","Unexpected matches can multiply or drop records and distort results."],["AI","Model Evaluation","Measure model performance without misleading conclusions.","Choose a baseline for comparison.|Use appropriate validation splits.|Select metrics for the business question.|Inspect confusion matrices where relevant.|Check leakage, imbalance and overfitting.|Report uncertainty and failure cases.","Write an evaluation report for a practice classifier.","When can accuracy be misleading?","When class imbalance or different error costs hide important mistakes."],["AI","Prompt Engineering","Design clearer tasks and evaluate generated responses.","State the task and desired outcome.|Provide relevant context and constraints.|Specify a useful response format.|Test with representative examples.|Inspect failures and revise instructions.|Protect sensitive information in the workflow.","Compare prompts for summarising a fictional project brief.","Why test prompts against several examples?","A prompt that works once may fail on other inputs or edge cases."],["AI","LLM APIs","Integrate language-model responses into an application.","Keep API credentials on the server.|Define and validate the user request.|Handle timeouts and upstream failures.|Extract the useful response content.|Monitor usage and output length.|Check generated output before acting on it.","Build an AI-assisted summary feature using non-sensitive sample text.","Should provider credentials be sent to the browser?","No. API requests using secrets belong on a trusted server."],["AI","RAG","Connect document retrieval with grounded answers.","Prepare documents for search.|Choose meaningful text segments.|Retrieve content relevant to the question.|Generate an answer using source context.|Show references supporting the response.|Test unsupported questions and weak retrieval.","Design a document-answering demo with visible source references.","Does retrieval guarantee a correct answer?","No. Retrieved material and generated claims still require evaluation."],["AI","AI Agents","Build bounded workflows that can use tools.","Define the goal and permitted actions.|Give tools narrow inputs and outputs.|Validate tool arguments and results.|Require approval for consequential actions.|Set stopping rules and recovery behaviour.|Compare the agent with a simpler fixed workflow.","Plan an assistant that drafts a task and asks before taking action.","Why give an agent explicit stopping rules?","They prevent uncontrolled retries and help keep work within the intended scope."],["AI","AI Coding Tools","Use code generation while retaining ownership of changes.","Describe the task and project constraints.|Limit the scope of the requested change.|Inspect generated code and dependencies.|Check behaviour with meaningful tests.|Keep secrets out of prompts and source.|Document decisions you can explain independently.","Review an AI-generated change and record accepted and rejected suggestions.","Who remains responsible for generated changes?","The developer who reviews and integrates them."],["Web3","Solidity","Understand smart-contract logic through a small practice project.","Model state and allowed operations.|Define access rules and validation.|Understand transaction execution and gas.|Test expected and rejected operations.|Review external calls and failure behaviour.|Use a test environment before considering real deployment.","Write a small test-only contract with documented access rules.","Why test rejected operations?","To confirm invalid or unauthorised actions cannot change protected state."],["Web3","Ethereum","Understand how an application interacts with a blockchain.","Distinguish accounts, contracts and networks.|Connect an interface to a test wallet.|Read contract state without a transaction.|Explain what a transaction requests.|Show pending, confirmed and failed states.|Keep test-only demonstrations separate from real funds.","Build a test-network interface that reads a sample contract.","Is a submitted transaction already confirmed?","No. Submission and confirmation are different states."],["Mobile","Flutter","Build a mobile interface with clear application structure.","Organise screens using reusable widgets.|Manage state for user interactions.|Create navigation between screens.|Load data with appropriate failure states.|Store suitable local application preferences.|Check layout and behaviour on a device.","Build a small mobile catalogue with a details screen.","Why check the application on a device?","Screen size, input, performance and platform behaviour affect usability."],["Full Stack","Docker","Package an application with repeatable runtime configuration.","Describe the application’s runtime needs.|Create an image with a clear build process.|Keep unnecessary files out of the image.|Configure environment variables safely.|Connect application and database services.|Document how to start and stop the environment.","Containerise a small practice API with setup instructions.","How does an image differ from a container?","An image describes the packaged environment; a container is a running instance."],["Backend","Data Structures","Choose data organisations that fit the problem.","Compare arrays and linked structures.|Use maps for key-based lookup.|Understand stacks and queues.|Explore trees, heaps and graphs.|Describe time and space costs.|Test empty inputs and boundary cases.","Create a small interview reference with implementations and examples.","Why choose a structure before coding?","Its supported operations and costs influence the quality of the solution."],["Backend","Algorithms","Solve common problems with explainable approaches.","Clarify inputs, outputs and constraints.|Start with a correct simple solution.|Recognise search, sorting and traversal patterns.|Use recursion or iteration deliberately.|Explain complexity and trade-offs.|Test edge cases and document the reasoning.","Solve a selection of practice problems and explain each approach.","What should precede optimisation?","A correct solution and a clear understanding of its constraints."],["Backend","OOP","Model software responsibilities through objects and interfaces.","Define cohesive classes and responsibilities.|Encapsulate implementation details.|Choose composition or inheritance carefully.|Use interfaces for suitable boundaries.|Avoid tight coupling between components.|Test behaviour through clear public interfaces.","Model a fictional booking workflow using a small set of classes.","Why avoid overly coupled classes?","Changes become harder to isolate, review and test."],["Backend","Design Patterns","Use established structures when they solve a real design problem.","Identify the recurring problem first.|Compare a simple solution with a pattern.|Explore creation and composition approaches.|Separate changing behaviour behind interfaces.|Refactor without changing required behaviour.|Explain the added complexity and benefit.","Refactor a small feature and justify whether a pattern helps.","Should every feature use a design pattern?","No. Apply a pattern only when its benefit outweighs the complexity."],["Backend","System Design","Explain the structure and trade-offs of a practical system.","Clarify expected users and core workflows.|Identify components and data boundaries.|Choose APIs and storage needs.|Consider caching and background work.|Plan failures and operational visibility.|Explain trade-offs and growth constraints.","Sketch a fictional appointment platform and discuss bottlenecks.","What should drive an architecture decision?","The system’s requirements, constraints and expected operating conditions."],["Full Stack","Testing","Verify important behaviour at useful boundaries.","Choose requirements worth checking.|Write focused tests for application logic.|Check APIs and validation boundaries.|Cover errors and edge cases.|Keep tests independent and repeatable.|Use automated checks when changes are made.","Create tests for a form and its API.","What makes a test useful?","It verifies meaningful behaviour and can reveal a real regression."],["Data","SQL for Analytics","Answer business questions using structured queries.","Define a clear metric and time window.|Filter records using consistent rules.|Aggregate and compare relevant groups.|Use joins without double-counting.|Explore ranking and window calculations.|Validate totals and explain limitations.","Analyse fictional product activity using queries and a short report.","Why define a metric before querying?","Different definitions can produce different answers to the same business question."],["Data","Statistics","Understand data variation and the limits of evidence.","Compare typical values with mean and median.|Describe spread and unusual observations.|Understand samples and selection bias.|Distinguish association from causation.|Represent uncertainty honestly.|Match conclusions to the available evidence.","Compare two fictional groups and explain what the data cannot establish.","Does correlation prove causation?","No. Confounding variables or chance can explain an association."],["Data","Data Visualisation","Communicate data with clear and honest charts.","Start with the question the chart answers.|Choose a suitable visual representation.|Label units, axes and categories.|Use colour to clarify meaning.|Avoid misleading scales or comparisons.|Review the chart alongside the underlying values.","Create a small dashboard from a fictional business dataset.","When is a line chart appropriate?","When showing an ordered sequence, often change over time."],["Backend","Java","Build a structured command-line application.","Understand values, control flow and types.|Organise logic into classes and methods.|Use collections for practical tasks.|Read data and handle exceptions.|Write checks for application behaviour.|Document building and running the project.","Build a fictional inventory command-line tool.","Why handle exceptions deliberately?","To give meaningful recovery or failure behaviour instead of hiding errors."],["Backend","C++","Write predictable programs with careful resource handling.","Understand types, control flow and functions.|Use standard containers and algorithms.|Organise behaviour through classes.|Manage resource lifetime deliberately.|Inspect compiler warnings and errors.|Test boundary cases and document build steps.","Build a small command-line data-processing project.","What does RAII help manage?","Resources whose lifetime should follow the lifetime of an owning object."],["Backend","Go","Build a small service with clear interfaces and error handling.","Use types and functions to express behaviour.|Organise a project into packages.|Handle errors explicitly.|Build HTTP handlers and validate requests.|Use concurrency only where needed.|Test and document the running service.","Create a small HTTP service with validation and tests.","Why handle errors explicitly?","It makes failure paths visible and supports deliberate recovery."],["Backend","Rust","Use ownership and types to write dependable application logic.","Understand ownership and borrowing.|Model values using structs and enums.|Handle recoverable errors with Result.|Work with collections and iterators.|Use modules and tests to organise the project.|Document how to build and run a small tool.","Build a command-line tool that validates a sample file.","Why use Result for recoverable errors?","It makes success and failure explicit in the function’s contract."],["Frontend","HTML & CSS","Build accessible page structure and responsive layouts.","Use semantic landmarks and headings.|Create labelled, keyboard-friendly forms.|Understand the box model and sizing.|Arrange content with Flexbox and Grid.|Adapt layouts to smaller screens.|Check readability, contrast and focus states.","Build a responsive landing page with a working navigation structure.","Why use semantic HTML?","It gives content meaningful structure for browsers and assistive technology."]];
let skillCategory="All";
const skillGrid=document.querySelector("#skill-cards"),skillSearch=document.querySelector("#skill-search");
function renderSkills(){if(!skillGrid||!skillSearch)return;const query=skillSearch.value.trim().toLowerCase();const list=skillGuides.filter(s=>(skillCategory==="All"||s[0]===skillCategory)&&(s[1]+" "+s[2]+" "+s[3]).toLowerCase().includes(query));skillGrid.replaceChildren();list.forEach(([category,name,description,lessons,practice,question,answer])=>{const card=document.createElement("article");card.className="skill-card";const cat=document.createElement("span");cat.className="skill-category";cat.textContent=category;const title=document.createElement("h3");const skillSlug=name.toLowerCase().replace(/\+/g,"plus").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");const titleLink=document.createElement("a");titleLink.textContent=name;titleLink.href="skill.html?skill="+encodeURIComponent(skillSlug);title.append(titleLink);const intro=document.createElement("p");intro.textContent=description;const detail=document.createElement("details");const summary=document.createElement("summary");summary.textContent="Explore this skill";detail.append(summary);const list=document.createElement("ol");lessons.split("|").forEach(l=>{const li=document.createElement("li");li.textContent=l;list.append(li)});const task=document.createElement("p");task.className="practice";task.textContent="Practice: "+practice;const check=document.createElement("details");check.className="self-check";const checkTitle=document.createElement("summary");checkTitle.textContent="Self-check: "+question;const checkAnswer=document.createElement("p");checkAnswer.textContent=answer;check.append(checkTitle,checkAnswer);detail.append(list,task,check);const link=document.createElement("a");link.href="contact.html#enquiry";link.textContent="Start Learning";link.href="lesson.html?skill="+encodeURIComponent(skillSlug)+"&lesson=1";card.append(cat,title,intro,detail,link);skillGrid.append(card)});document.querySelector("#skill-results").textContent=list.length+" skills found";if(!list.length){const empty=document.createElement("p");empty.textContent="No matching skills. Try another keyword or choose All Skills.";skillGrid.append(empty)}}
skillSearch?.addEventListener("input",renderSkills);
document.querySelectorAll("[data-skill-category]").forEach(b=>b.addEventListener("click",()=>{skillCategory=b.dataset.skillCategory;document.querySelectorAll("[data-skill-category]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));renderSkills()}));renderSkills();
// Carry a selected program or service between pages using URL parameters.
if(type&&interest){const query=new URLSearchParams(location.search);const selectedType=query.get("type");if([...type.options].some(o=>o.value===selectedType)){type.value=selectedType;fillInterests()}const selectedInterest=query.get("interest");if([...interest.options].some(o=>o.value===selectedInterest))interest.value=selectedInterest;const message=query.get("message");if(message)document.querySelector('[name="message"]').value=message.slice(0,3000)}

// Cards move visually right to left. Autoplay pauses for hover, focus, interaction or reduced motion.
document.querySelectorAll(".showcase").forEach(row=>{
const controls=document.querySelector('[data-controls="'+row.id+'"]'),pause=controls.querySelector("[data-pause]");let stopped=matchMedia("(prefers-reduced-motion: reduce)").matches,hover=false,focus=false,last=0,interactionUntil=0;
row.scrollLeft=0;
pause.textContent=stopped?"Play":"Pause";pause.setAttribute("aria-pressed",String(stopped));
pause.addEventListener("click",()=>{stopped=!stopped;pause.textContent=stopped?"Play":"Pause";pause.setAttribute("aria-pressed",String(stopped))});
controls.querySelector("[data-prev]").addEventListener("click",()=>{interactionUntil=performance.now()+8000;row.scrollBy({left:-360,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})});
controls.querySelector("[data-next]").addEventListener("click",()=>{interactionUntil=performance.now()+8000;row.scrollBy({left:360,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})});
row.addEventListener("mouseenter",()=>hover=true);row.addEventListener("mouseleave",()=>hover=false);row.addEventListener("focusin",()=>focus=true);row.addEventListener("focusout",()=>focus=row.contains(document.activeElement));
["wheel","touchstart","pointerdown","keydown"].forEach(event=>row.addEventListener(event,()=>{interactionUntil=performance.now()+8000},{passive:true}));
function tick(now){const dt=Math.min(now-last,60);last=now;if(!stopped&&!hover&&!focus&&!document.hidden&&now>interactionUntil&&row.scrollWidth>row.clientWidth){if(row.scrollLeft>=row.scrollWidth-row.clientWidth-1){row.scrollLeft=0}else row.scrollLeft+=dt*.025}requestAnimationFrame(tick)}
pause.addEventListener("click",()=>{if(!stopped&&row.scrollLeft>=row.scrollWidth-row.clientWidth-1)row.scrollLeft=0});requestAnimationFrame(tick);
});

// Accessible native dropdowns: close siblings, outside clicks and Escape.
const navMenus=[...document.querySelectorAll(".nav-dropdown")];navMenus.forEach(menu=>menu.addEventListener("toggle",()=>{if(menu.open)navMenus.forEach(other=>{if(other!==menu)other.open=false})}));document.addEventListener("click",event=>{if(!event.target.closest("#navigation"))navMenus.forEach(menu=>menu.open=false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"){const opened=navMenus.find(menu=>menu.open);navMenus.forEach(menu=>menu.open=false);opened?.querySelector("summary").focus()}});
